def _normalize_kind(kind: str) -> str:
    aliases = {'membership': 'catalog_price', 'translation': 'form', 'delivery': 'form', 'courier': 'form', 'status': 'form', 'sponsor': 'form', 'verification': 'form', 'repair_center': 'form', 'affiliate': 'referral', 'subscription': 'catalog_price', 'vip_club': 'catalog_price', 'rewards': 'loyalty', 'fundraising': 'donation', 'roommate': 'catalog', 'jobs': 'catalog', 'classified': 'catalog_price', 'realestate': 'catalog_price', 'rental': 'catalog_price', 'car_rental': 'catalog_price', 'hotel': 'catalog_price', 'travel': 'catalog', 'podcast': 'content', 'news': 'content', 'magazine': 'content', 'tutorial': 'content', 'daily_digest': 'content', 'media_hub': 'content', 'link_catalog': 'links', 'content_library': 'content', 'admin_publisher': 'channel', 'announcement': 'content', 'release_notes': 'content', 'webinar': 'event', 'conference': 'event', 'workshop': 'event', 'meetup': 'event', 'fan_club': 'community', 'contest': 'quiz', 'trivia': 'quiz', 'exam_prep': 'quiz', 'language_school': 'catalog', 'academy': 'catalog', 'course': 'catalog_price', 'ebook': 'catalog', 'directory': 'catalog', 'menu': 'catalog', 'service_order': 'catalog_price', 'restaurant': 'catalog_price', 'cafe': 'catalog_price', 'bakery': 'catalog_price', 'flower_shop': 'catalog_price', 'gift_shop': 'catalog_price', 'fashion_shop': 'catalog_price', 'digital_shop': 'catalog_price', 'wholesale': 'catalog_price', 'agency': 'catalog', 'marketing': 'catalog', 'design_studio': 'catalog', 'software_company': 'catalog', 'business_consulting': 'booking', 'legal': 'form', 'accounting': 'form', 'insurance': 'form', 'printing': 'form', 'appointment': 'booking', 'clinic': 'booking', 'dentist': 'booking', 'beauty': 'booking', 'barber': 'booking', 'gym': 'booking', 'photography': 'booking', 'car_service': 'booking', 'pet_clinic': 'booking', 'training_center': 'catalog', 'library': 'catalog', 'event_register': 'event'}
    return aliases.get(kind, kind)

def parse_detail(kind: str, raw: str) -> dict:
    raw = (raw or "").strip()
    if raw == "/empty": raw = ""
    k = _normalize_kind(kind)
    if k in {"catalog_price","catalog"}:
        out=[]
        for line in raw.splitlines():
            parts=[p.strip() for p in line.split("|",2)]
            if len(parts)>=2: out.append({"name":parts[0],"price":parts[1],"desc":parts[2] if len(parts)>2 else ""} if k=="catalog_price" else {"name":parts[0],"desc":parts[1]})
        return {"items":out}
    if k=="booking": return {"slots":[x.strip() for x in raw.splitlines() if x.strip()]}
    if k=="quiz":
        qs=[]
        for line in raw.splitlines():
            p=[x.strip() for x in line.split("|",2)]
            if len(p)!=3: continue
            opts=[x.strip() for x in p[1].split(",") if x.strip()]
            try: correct=int(p[2])-1
            except: continue
            if opts and 0<=correct<len(opts): qs.append({"q":p[0],"options":opts,"correct":correct})
        return {"questions":qs}
    if k=="poll":
        p=[x.strip() for x in raw.split("|",1)]; return {"question": p[0] if p else "نظرت چیست؟", "options":[x.strip() for x in p[1].split(",") if x.strip()] if len(p)>1 else []}
    if k=="event": return {"items":[{"name":p[0].strip(),"desc":p[1].strip()} for line in raw.splitlines() if len(p:=line.split("|",1))==2]}
    if k=="links": return {"links":[{"title":p[0].strip(),"url":p[1].strip()} for line in raw.splitlines() if len(p:=line.split("|",1))==2]}
    if k=="file_store": return {"files":[{"title":p[0].strip(),"file_id":p[1].strip()} for line in raw.splitlines() if len(p:=line.split("|",1))==2]}
    if k=="content": return {"items":[{"title":p[0].strip(),"text":p[1].strip()} for line in raw.splitlines() if len(p:=line.split("|",1))==2]}
    if k=="channel": return {"channel": raw if raw.startswith("@") else "@"+raw if raw else "@yourchannel"}
    if k=="rules": return {"rules":raw}
    if k in {"form","feedback"}: return {"fields":[x.strip() for x in raw.split(",") if x.strip()]}
    if k=="faq": return {"items":[{"q":p[0].strip(),"a":p[1].strip()} for line in raw.splitlines() if len(p:=line.split("|",1))==2]}
    if k=="coupon": return {"coupons":[x.strip() for x in raw.split(",") if x.strip()]}
    if k=="donation": return {"campaign":raw}
    return {"detail":raw}

