# Make every template a distinct commercial product profile, while sharing a tested core.
for _key in TEMPLATES:
    eng = ENGINE_BY_KEY.get(_key, _normalize_kind(TEMPLATE_META[_key]['kind']))
    TEMPLATE_META[_key]['engine'] = eng
    TEMPLATE_META[_key]['features'] = sorted(FEATURES_BY_ENGINE.get(eng, {'profile','support'}))


def build_bot(data: dict) -> str:
    key = data['template']
    if key not in TEMPLATES:
        raise ValueError('قالب نامعتبر است.')
    raw_detail = data.get('detail', '')
    parsed = parse_detail(TEMPLATE_META[key]['kind'], raw_detail)
    cfg = {**data, **parsed}
    cfg['profile'] = {
        'key': key,
        'label': TEMPLATES[key],
        'category': TEMPLATE_META[key]['category'],
        'engine': TEMPLATE_META[key]['engine'],
        'features': TEMPLATE_META[key]['features'],
    }
    cfg['channel'] = cfg.get('channel', '@yourchannel')
    return _render_generated(cfg, TEMPLATES[key])


def _render_generated(cfg: dict, label: str) -> str:
    code = _GENERATOR_TEMPLATE
    replacements = {
        '__CHANNEL__': _q(cfg.get('channel','@yourchannel')),
        '__BRAND__': _q(cfg['brand_name']),
        '__WELCOME__': _q(cfg['welcome_text']),
        '__TEMPLATE__': _q(label),
        '__CONFIG__': _q(cfg),
    }
    for placeholder, value in replacements.items():
        code = code.replace(placeholder, value)
    return code



_GENERATOR_TEMPLATE = base64.b64decode('').decode('utf-8')

def build_bot(data: dict) -> str:
    key=data["template"]
    if key not in TEMPLATES:
        raise ValueError("قالب نامعتبر است.")
    cfg={**data, **parse_detail(TEMPLATE_META[key]["kind"], data.get("detail",""))}
    cfg["profile"]={
        "key":key,
        "label":TEMPLATES[key],
        "category":TEMPLATE_META[key]["category"],
        "engine":TEMPLATE_META[key]["engine"],
        "features":TEMPLATE_META[key]["features"],
    }
    return _render_generated(cfg,TEMPLATES[key])


def _render_generated(cfg: dict, label: str) -> str:
    code=_GENERATOR_TEMPLATE
    for placeholder,value in {
        "__CHANNEL__":_q(cfg.get("channel","@yourchannel")),
        "__BRAND__":_q(cfg["brand_name"]),
        "__WELCOME__":_q(cfg["welcome_text"]),
        "__TEMPLATE__":_q(label),
        "__CONFIG__":_q(cfg),
    }.items():
        code=code.replace(placeholder,value)
    return code



